const body = $json.body ?? $json;
const name = String(body.name || '').trim();
const email = String(body.email || '').trim().toLowerCase();
const company = String(body.company || '').trim();
const monthlyContacts = Number(body.monthlyContacts || 0);
const channels = Array.isArray(body.channels) ? body.channels.map(value => String(value).toLowerCase()) : [];
const useCase = String(body.useCase || '').trim();
const currentTools = Array.isArray(body.currentTools) ? body.currentTools : [];
const urgency = String(body.urgency || 'media').trim().toLowerCase();

if (!name || !email || !company) {
  return [{ json: { success: false, error: 'name, email y company son obligatorios para agendar una demo.' } }];
}

const bundles = [];
if (channels.includes('whatsapp')) bundles.push('Alertas transaccionales por WhatsApp');
if (channels.includes('email')) bundles.push('Secuencias de email y resumenes automaticos');
if (channels.includes('sms')) bundles.push('Recordatorios criticos por SMS');
if (channels.includes('push')) bundles.push('Eventos push para app o panel interno');
if (!bundles.length) bundles.push('Arquitectura base de eventos y reglas de notificacion');

const score =
  (monthlyContacts >= 50000 ? 4 : monthlyContacts >= 10000 ? 3 : monthlyContacts > 0 ? 2 : 1) +
  Math.min(channels.length, 3) +
  (urgency === 'alta' ? 2 : urgency === 'media' ? 1 : 0) +
  (currentTools.length ? 1 : 0);

const segment = score >= 8 ? 'enterprise' : score >= 5 ? 'growth' : 'starter';
const recommendedTrack = segment === 'enterprise'
  ? 'Workshop tecnico + roadmap de integraciones + piloto de alto volumen'
  : segment === 'growth'
    ? 'Demo comercial + blueprint de flujos + piloto de 2 a 4 semanas'
    : 'Demo corta + setup inicial + primera automatizacion cerrada';

const brief = {
  lead: { name, email, company },
  segment,
  use_case: useCase || 'notificaciones automatizadas',
  channels,
  monthly_contacts: monthlyContacts,
  current_tools: currentTools,
  urgency,
  bundles,
  recommended_track: recommendedTrack,
  next_step: 'Agendar demo con discovery orientado a eventos, canales y ROI.'
};

const staticData = $getWorkflowStaticData('global');
staticData.requests = Array.isArray(staticData.requests) ? staticData.requests : [];
staticData.requests.unshift({
  created_at: new Date().toISOString(),
  ...brief
});
staticData.requests = staticData.requests.slice(0, 500);

return [{
  json: {
    success: true,
    segment,
    recommended_track: recommendedTrack,
    bundles,
    brief,
    registry_size: staticData.requests.length,
    message: `Solicitud registrada para ${company}. Recomiendo ${recommendedTrack}.`
  }
}];
